"use client";

import React, { useState, useRef, useEffect } from "react";
import FullCalendar from "@fullcalendar/react";
import dayGridPlugin from "@fullcalendar/daygrid";
import interactionPlugin from "@fullcalendar/interaction";
import timeGridPlugin from "@fullcalendar/timegrid";
import listPlugin from "@fullcalendar/list";
import { 
  X, Calendar as CalendarIcon, ChevronLeft, ChevronRight, 
  Filter, Plus, User, Users, CheckCircle2, Clock, MapPin 
} from "lucide-react";
import { Modal } from "@/components/ui/modal";

// --- Types ---
type EventType = "holiday" | "personal" | "team" | "pending";

interface CalendarEvent {
  id: string;
  title: string;
  start: string;
  end?: string;
  type: EventType;
  extendedProps?: {
    avatar?: string;
    description?: string;
    status?: string;
  };
  classNames?: string[];
  backgroundColor?: string;
  borderColor?: string;
}

// --- Mock Data ---
const INITIAL_EVENTS: CalendarEvent[] = [
  { 
    id: "1", 
    title: "New Year", 
    start: "2025-01-01", 
    type: "holiday", 
    backgroundColor: "#10B981", 
    borderColor: "#10B981",
    extendedProps: { description: "Public Holiday" }
  },
  { 
    id: "2", 
    title: "Dental Appt", 
    start: "2025-02-05", 
    type: "personal", 
    backgroundColor: "#3B82F6", 
    borderColor: "#3B82F6",
    extendedProps: { status: "Approved", description: "Leaving early" }
  },
  { 
    id: "3", 
    title: "Japan Trip", 
    start: "2025-02-10", 
    end: "2025-02-14", 
    type: "personal", 
    backgroundColor: "#3B82F6", 
    borderColor: "#3B82F6",
    extendedProps: { status: "Approved" }
  },
  { 
    id: "4", 
    title: "John (Sick)", 
    start: "2025-02-06", 
    type: "team", 
    backgroundColor: "#F59E0B", 
    borderColor: "#F59E0B",
    extendedProps: { avatar: "JD" }
  },
  { 
    id: "5", 
    title: "Sarah (Remote)", 
    start: "2025-02-06", 
    type: "team", 
    backgroundColor: "#8B5CF6", 
    borderColor: "#8B5CF6",
    extendedProps: { avatar: "SM" }
  },
];

export default function UltimateCalendarPage() {
  const calendarRef = useRef<FullCalendar>(null);
  const [events, setEvents] = useState<CalendarEvent[]>(INITIAL_EVENTS);
  const [activeFilters, setActiveFilters] = useState<EventType[]>(["holiday", "personal", "team", "pending"]);
  
  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedRange, setSelectedRange] = useState<{start: string, end: string} | null>(null);
  const [requestForm, setRequestForm] = useState({ type: "Annual", reason: "" });

  // Sidebar State (Day Details)
  const [selectedDayEvents, setSelectedDayEvents] = useState<CalendarEvent[]>([]);
  const [selectedDateStr, setSelectedDateStr] = useState<string>("");
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // --- Handlers ---

  const handleDateSelect = (selectInfo: any) => {
    setSelectedRange({ 
      start: selectInfo.startStr, 
      end: selectInfo.endStr 
    });
    // Filter events for this day to show in sidebar context first
    const dayEvents = events.filter(e => 
      e.start >= selectInfo.startStr && (e.end || e.start) <= selectInfo.endStr
    );
    setSelectedDayEvents(dayEvents);
    setSelectedDateStr(selectInfo.startStr);
    setIsSidebarOpen(true);
  };

  const handleEventClick = (clickInfo: any) => {
    // Open details for existing event
    alert(`Event: ${clickInfo.event.title}\nDescription: ${clickInfo.event.extendedProps.description || 'N/A'}`);
  };

  const toggleFilter = (type: EventType) => {
    setActiveFilters(prev => 
      prev.includes(type) ? prev.filter(t => t !== type) : [...prev, type]
    );
  };

  const submitLeaveRequest = () => {
    if (!selectedRange) return;
    
    const newEvent: CalendarEvent = {
      id: Date.now().toString(),
      title: `${requestForm.type} (Pending)`,
      start: selectedRange.start,
      end: selectedRange.end,
      type: "pending",
      backgroundColor: "#94A3B8", // Gray for pending
      borderColor: "#94A3B8",
      classNames: ["animate-pulse"], // Visual cue for pending
      extendedProps: { status: "Pending", description: requestForm.reason }
    };

    setEvents([...events, newEvent]);
    setIsModalOpen(false);
    setIsSidebarOpen(false);
    setRequestForm({ type: "Annual", reason: "" });
  };

  const filteredEvents = events.filter(e => activeFilters.includes(e.type));

  return (
    <div className="mx-auto max-w-[1600px] h-[calc(100vh-100px)] flex flex-col gap-6 p-2">
      
      {/* 1. Header & Controls */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white dark:bg-[#111] p-4 rounded-2xl border border-gray-200 dark:border-gray-800 shadow-sm">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
            <CalendarIcon className="h-6 w-6 text-blue-600" />
            Team Calendar
          </h1>
          <p className="text-sm text-gray-500 dark:text-gray-400">Manage schedule and view availability</p>
        </div>

        <div className="flex items-center gap-3">
          {/* Custom Navigation */}
          <div className="flex items-center bg-gray-100 dark:bg-white/5 rounded-lg p-1">
            <button onClick={() => calendarRef.current?.getApi().prev()} className="p-2 hover:bg-white dark:hover:bg-white/10 rounded-md shadow-sm transition-all"><ChevronLeft size={16}/></button>
            <button onClick={() => calendarRef.current?.getApi().today()} className="px-4 text-sm font-semibold">Today</button>
            <button onClick={() => calendarRef.current?.getApi().next()} className="p-2 hover:bg-white dark:hover:bg-white/10 rounded-md shadow-sm transition-all"><ChevronRight size={16}/></button>
          </div>

          <button 
            onClick={() => {
                const today = new Date().toISOString().split('T')[0];
                setSelectedRange({ start: today, end: today });
                setIsModalOpen(true);
            }} 
            className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2.5 rounded-xl font-medium shadow-lg shadow-blue-500/20 transition-all"
          >
            <Plus size={18} />
            <span>New Request</span>
          </button>
        </div>
      </div>

      <div className="flex flex-1 gap-6 overflow-hidden">
        
        {/* 2. Main Calendar Area */}
        <div className="flex-1 bg-white dark:bg-[#111] rounded-2xl border border-gray-200 dark:border-gray-800 p-2 shadow-sm overflow-hidden flex flex-col">
          
          {/* Filters Bar */}
          <div className="flex flex-wrap gap-3 p-4 border-b border-gray-100 dark:border-gray-800 mb-2">
            <div className="flex items-center gap-2 text-sm text-gray-500 mr-2">
              <Filter size={14} />
              <span>Filters:</span>
            </div>
            {[
              { id: "holiday", label: "Holidays", color: "bg-emerald-500" },
              { id: "personal", label: "My Leaves", color: "bg-blue-500" },
              { id: "team", label: "Team", color: "bg-amber-500" },
              { id: "pending", label: "Pending", color: "bg-gray-400" },
            ].map((f) => (
              <button
                key={f.id}
                onClick={() => toggleFilter(f.id as EventType)}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-medium transition-all ${
                  activeFilters.includes(f.id as EventType)
                    ? "bg-gray-100 dark:bg-white/10 text-gray-900 dark:text-white ring-1 ring-gray-200 dark:ring-gray-700"
                    : "opacity-50 hover:opacity-100"
                }`}
              >
                <span className={`w-2 h-2 rounded-full ${f.color}`} />
                {f.label}
              </button>
            ))}
          </div>

          <div className="flex-1 custom-calendar-wrapper">
            <FullCalendar
              ref={calendarRef}
              plugins={[dayGridPlugin, interactionPlugin, timeGridPlugin, listPlugin]}
              initialView="dayGridMonth"
              headerToolbar={false} // Custom toolbar used above
              events={filteredEvents}
              selectable={true}
              selectMirror={true}
              dayMaxEvents={true}
              weekends={true}
              select={handleDateSelect}
              eventClick={handleEventClick}
              height="100%"
              // Custom Render for events to add avatars/icons
              eventContent={(arg) => {
                return (
                  <div className="flex items-center gap-1 overflow-hidden px-1 py-0.5 w-full">
                    {arg.event.extendedProps.avatar && (
                      <div className="w-4 h-4 rounded-full bg-white/20 text-[8px] flex items-center justify-center text-white font-bold">
                        {arg.event.extendedProps.avatar}
                      </div>
                    )}
                    <div className="text-xs truncate font-medium">{arg.event.title}</div>
                  </div>
                )
              }}
            />
          </div>
        </div>

        {/* 3. Context Sidebar (Appears when date is clicked) */}
        {isSidebarOpen && (
          <div className="w-80 bg-white dark:bg-[#111] border-l border-gray-200 dark:border-gray-800 p-6 flex flex-col gap-6 animate-in slide-in-from-right duration-200 shadow-2xl z-10 absolute right-0 top-0 bottom-0 lg:relative lg:shadow-none">
            
            <div className="flex items-center justify-between">
              <h2 className="text-xl font-bold text-gray-900 dark:text-white">
                {new Date(selectedDateStr).toLocaleDateString('en-US', { weekday: 'short', day: 'numeric', month: 'long' })}
              </h2>
              <button onClick={() => setIsSidebarOpen(false)} className="p-2 hover:bg-gray-100 dark:hover:bg-white/10 rounded-full">
                <X size={18} />
              </button>
            </div>

            {/* Day Context */}
            <div className="space-y-4">
              <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider">On this day</h3>
              
              {selectedDayEvents.length > 0 ? (
                <div className="space-y-3">
                  {selectedDayEvents.map(e => (
                    <div key={e.id} className="flex items-start gap-3 p-3 rounded-xl bg-gray-50 dark:bg-white/5 border border-gray-100 dark:border-gray-800">
                      <div className={`w-1 h-full rounded-full ${e.backgroundColor === '#10B981' ? 'bg-emerald-500' : 'bg-blue-500'} min-h-[30px]`} />
                      <div>
                        <p className="text-sm font-semibold text-gray-900 dark:text-white">{e.title}</p>
                        <p className="text-xs text-gray-500 mt-0.5 flex items-center gap-1">
                          {e.type === 'team' && <Users size={12} />}
                          {e.extendedProps?.description || e.type.toUpperCase()}
                        </p>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-8 text-gray-400 bg-gray-50 dark:bg-white/5 rounded-xl border border-dashed border-gray-200 dark:border-gray-700">
                  <p className="text-sm">No events scheduled</p>
                  <p className="text-xs mt-1">Everyone is available</p>
                </div>
              )}
            </div>

            {/* Quick Actions */}
            <div className="mt-auto">
              <button 
                onClick={() => setIsModalOpen(true)}
                className="w-full bg-gray-900 dark:bg-white text-white dark:text-black py-3 rounded-xl font-semibold shadow-lg hover:opacity-90 transition-opacity flex items-center justify-center gap-2"
              >
                <Plus size={18} />
                Request This Day
              </button>
            </div>
          </div>
        )}
      </div>

      {/* 4. Leave Request Modal */}
      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} className="max-w-md p-0 overflow-hidden">
        <div className="bg-gray-50 dark:bg-white/5 px-6 py-4 border-b border-gray-100 dark:border-gray-800 flex justify-between items-center">
          <h3 className="font-bold text-lg">Request Time Off</h3>
          <button onClick={() => setIsModalOpen(false)}><X size={20} className="text-gray-400" /></button>
        </div>
        
        <div className="p-6 space-y-5">
          {/* Date Summary */}
          <div className="flex items-center gap-3 bg-blue-50 dark:bg-blue-900/20 p-3 rounded-xl border border-blue-100 dark:border-blue-900/30 text-blue-800 dark:text-blue-200">
            <CalendarIcon size={20} />
            <div className="text-sm font-medium">
              {selectedRange?.start} 
              {selectedRange?.end && selectedRange.start !== selectedRange.end ? ` ➔ ${selectedRange.end}` : ''}
            </div>
          </div>

          <div className="space-y-4">
            <div>
              <label className="block text-xs font-semibold text-gray-500 uppercase mb-1.5">Leave Category</label>
              <select 
                className="w-full p-2.5 bg-white dark:bg-[#111] border border-gray-200 dark:border-gray-700 rounded-lg text-sm outline-none focus:ring-2 ring-blue-500"
                value={requestForm.type}
                onChange={(e) => setRequestForm({...requestForm, type: e.target.value})}
              >
                <option value="Annual">Annual Leave (Vacation)</option>
                <option value="Sick">Sick Leave</option>
                <option value="Casual">Casual Leave</option>
                <option value="Remote">Work From Home</option>
              </select>
            </div>
            
            <div>
              <label className="block text-xs font-semibold text-gray-500 uppercase mb-1.5">Reason</label>
              <textarea 
                className="w-full p-3 bg-white dark:bg-[#111] border border-gray-200 dark:border-gray-700 rounded-lg text-sm outline-none focus:ring-2 ring-blue-500 resize-none h-24"
                placeholder="Briefly describe why..."
                value={requestForm.reason}
                onChange={(e) => setRequestForm({...requestForm, reason: e.target.value})}
              />
            </div>
          </div>

          <div className="pt-2">
            <button 
              onClick={submitLeaveRequest}
              className="w-full bg-blue-600 hover:bg-blue-700 text-white py-3 rounded-xl font-medium transition-colors flex items-center justify-center gap-2"
            >
              <CheckCircle2 size={18} />
              Submit Request
            </button>
          </div>
        </div>
      </Modal>

      {/* Global Styles for FullCalendar Customization */}
      <style jsx global>{`
        .fc {
          --fc-border-color: #e5e7eb;
          --fc-button-bg-color: #2563eb;
          --fc-button-border-color: #2563eb;
          --fc-button-hover-bg-color: #1d4ed8;
          --fc-button-hover-border-color: #1d4ed8;
          --fc-today-bg-color: rgba(59, 130, 246, 0.05) !important;
          font-family: inherit;
        }
        .dark .fc {
          --fc-border-color: #1f2937;
          --fc-page-bg-color: #111;
          --fc-neutral-bg-color: #1f2937;
          --fc-list-event-hover-bg-color: #374151;
        }
        .fc .fc-col-header-cell-cushion {
          padding-top: 12px;
          padding-bottom: 12px;
          font-size: 0.85rem;
          font-weight: 600;
          text-transform: uppercase;
          color: #6b7280;
        }
        .fc-daygrid-day-number {
          font-size: 0.9rem;
          font-weight: 600;
          color: #374151;
          padding: 8px !important;
        }
        .dark .fc-daygrid-day-number {
          color: #d1d5db;
        }
        .fc-day-sat, .fc-day-sun {
          background-color: rgba(243, 244, 246, 0.4);
        }
        .dark .fc-day-sat, .dark .fc-day-sun {
          background-color: rgba(31, 41, 55, 0.2);
        }
        .fc-event {
          border-radius: 6px;
          border: none;
          box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
          font-size: 0.75rem;
          cursor: pointer;
          transition: transform 0.1s;
        }
        .fc-event:hover {
          transform: scale(1.02);
        }
      `}</style>
    </div>
  );
}